$b['A monumental Neo-Traditional composition where a dragon woman flowers storm clouds and architectural elements form one continuous scene designed entirely around the back rather than appearing as separate objects'] = 'Two panels side by side on one image, divided down the middle. LEFT PANEL: the tattoo design alone on a plain white background, shown flat exactly as described, no body, drawn large so it fills most of the panel. RIGHT PANEL: Studio photograph of a real person''s body showing the same exact tattoo where described, healed tattoo on real skin in soft even light, the rest of the body modestly covered by simple plain clothing, only the tattooed area bare, plain seamless light grey studio backdrop - no room, no furniture, no scenery. The tattoo in both panels is identical. The tattoo: A monumental Neo-Traditional composition where a dragon, woman, flowers, storm clouds and architectural elements form one continuous scene designed entirely around the back rather than appearing as separate objects. Epic, sophisticated, unforgettable. In the right panel it is on a woman, full back. Create premium contemporary Neo-Traditional tattoo artwork. The style must remain unmistakably Neo-Traditional while allowing extraordinary freedom in subject matter. Use: Bold readable silhouettes Strong confident outlines Varied line weight Rich dimensional color Controlled black structure Sophisticated illustrative rendering Clear focal hierarchy Decorative detail where it improves the composition Strong contrast Intentional negative space Beautiful color relationships Body-aware composition Do not reduce Neo-Traditional to: Lady heads Animal heads Flowers Ornamental frames Traditional flash subjects Those are valid subjects, but they are not the boundaries of the style. Do not automatically add flowers around every subject. Do not automatically put the subject inside an oval, circle, frame or symmetrical ornamental border. Allow artwork to: Wrap Climb Fall Turn Radiate Spiral Cross joints Follow muscles Follow bones Travel around limbs Move from one body region into another Vary the palette intelligently. Explore: Ruby Burgundy Cherry red Coral Burnt orange Gold Mustard Emerald Forest green Teal Turquoise Cobalt Royal blue Violet Lavender Dusty pink Hot pink Cream Warm brown Deep black Do not use every color in every tattoo. Build intentional palettes for each individual piece. THE BODY DETERMINES THE COMPOSITION. For every concept create a matched dual-card presentation. LEFT: The complete tattoo artwork isolated clearly on clean bright white. RIGHT: The exact same artwork professionally tattooed on the specified human body location. The body version must look like actual healed tattoo ink integrated into real skin. Do not redesign the tattoo between the two cards. Do not add or remove elements. Do not change colors. Do not change orientation. Do not change composition. The left card is the tattoo artwork. The right card proves how extraordinary that exact artwork can look on a human being. The human photograph should be aspirational without becoming fashion advertising. The tattoo remains the hero. Use believable bodies, believable skin, believable placement and believable tattoo scale. NEO-TRADITIONAL IS THE VISUAL LANGUAGE. THE SUBJECT CAN BE ANYTHING. THE BODY DETERMINES THE COMPOSITION. THE STYLE STAYS CONSTANT. THE IMAGINATION CHANGES'
$mine = @(); foreach ($c in $cats.Keys) { $mine += @($cats[$c].Keys) }
$taken = @{}; $tt.specific.PSObject.Properties | ? { $mine -notcontains $_.Name } | % { $_.Value | ? { $_ } | % { $taken[(& $slug $_)] = 1 } }
$final = @{}
foreach ($c in $cats.Keys) {
  $kinds = @($cats[$c].Keys)
  $had = @($tt.subjects.$c | ? { $_ }); "  " + $c + " already has " + $had.Count + " sets - the new ones are ADDED, nothing removed"
  foreach ($k in $kinds) { if ($had -contains $k) { "  SET NAME ALREADY IN THIS CATEGORY: " + $k; $clash = $true } }
  if ($tt.subjects.PSObject.Properties[$c]) { $tt.subjects.$c = @($had + $kinds) } else { $tt.subjects | Add-Member -NotePropertyName $c -NotePropertyValue $kinds }
  foreach ($k in $kinds) {
    $names = @($cats[$c][$k] | % { $o = $_; if ($taken.ContainsKey((& $slug $o))) { $nn = $o + " in " + $c + " Style"; "  RENAMED: " + $nn | Out-Host } else { $nn = $o }; $final[$o] = $nn; $nn })
    if ($tt.specific.PSObject.Properties[$k]) { $tt.specific.$k = $names } else { $tt.specific | Add-Member -NotePropertyName $k -NotePropertyValue $names }
  }
}
$json = $tt | ConvertTo-Json -Depth 20 -Compress
$check = $json | ConvertFrom-Json
$afterCats = @($check.subjects.PSObject.Properties).Count
if ($clash -or $afterCats -lt $beforeCats -or $json.Length -lt ($got.raw.Length * 0.9)) { "  SAFETY STOP - the new catalog looks smaller than the old one, nothing written" } else {
$tmp = Join-Path $env:TEMP "card-tree-new.json"
[System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding $false))
npx wrangler kv key put --namespace-id $ns "card:tree" --path $tmp --remote 2>$null | Out-Null
"  catalog written in ONE save: " + $beforeCats + " categories before, " + $afterCats + " after"
"  saving the split-card settings and the tattoo descriptions..."
$n = 0
foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) {
  $ks = & $slug $k
  RUN ("SETKV render:" + $ks + " The tattoo in both panels is identical.") | Out-Null
  RUN ("SETKV shape:" + $ks + " 3:2") | Out-Null
  RUN ("SETKV split:" + $ks + " yes") | Out-Null
  foreach ($o in $cats[$c][$k]) { RUN ("SETKV build:" + (& $slug $final[$o]) + " " + $b[$o]) | Out-Null; $n++ }
} }
"  " + $n + " descriptions saved - waiting 70 seconds so every server sees the new catalog..."
Start-Sleep -Seconds 70
