$want = @('context:neo-traditional-ii-animals-in-motion','context:neo-traditional-ii-beautiful-women-and-powerful-characters','context:neo-traditional-ii-designed-around-the-body','context:neo-traditional-ii-dragons-monsters-and-mythical-creatures','context:neo-traditional-ii-fantasy-and-impossible-worlds','context:neo-traditional-ii-flowers-nature-and-flow','context:neo-traditional-ii-gothic-dark-and-macabre','context:neo-traditional-ii-modern-subjects-in-neo-traditional','context:neo-traditional-ii-neo-traditional-classics-reimagined','context:neo-traditional-ii-push-neo-traditional')
$tmp = Join-Path $env:TEMP "aura-ctx-neo-traditional.json"
